/**
 * Official Reporting Pack issuance (supabase/functions/_shared/reportingPackSeal.mjs, security corrections B-4 / N-1):
 * the document is generated by the DATABASE from the authoritative saved output; no caller supplies bytes or a hash.
 * Here the handler runs against a model of the database's contract (prepare → canonical document; seal → the database
 * regenerates and hashes it itself). The real canonical renderer, the real seal and the adversarial byte cases are
 * proven on real PostgreSQL, through this same module, in scripts/db-proof/billingSuspension.mjs.
 */
import { createHash } from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { issueOfficialPack, parseSealRequest, verifyStoredPack, type SealDeps } from "../../../supabase/functions/_shared/reportingPackSeal.mjs";
import { deliverOfficialPack, deliverWorkingCopy, isOfficiallySealable, parseOfficialDocument } from "./reportingPack";

const sha = (b: Uint8Array) => createHash("sha256").update(b).digest("hex");
const shaText = (t: string) => sha(new TextEncoder().encode(t));
const U = { user: "11111111-1111-4111-8111-111111111111", iss: "22222222-2222-4222-8222-222222222222", co: "33333333-3333-4333-8333-333333333333" };
const PATH = `${U.co}/${U.iss}.json`;
// The canonical document the database renders from the saved output of this issuance (a non-ASCII amount label on
// purpose: the bytes are the UTF-8 encoding the database hashed).
const CANONICAL = '{\n    "schema": "cfoclose.official-reporting-pack.v1",\n    "report": {"revenue": "TZS 1 000 000 — audited"}\n}\n';
const DOCTORED = CANONICAL.replace("1 000 000", "9 000 000");

function world(opts: { prepare?: string; seal?: string; sealHash?: string; tamperOnPut?: boolean; prepHash?: string } = {}) {
  const store = new Map<string, Uint8Array>();
  const rpcCalls: Array<[string, Record<string, unknown>]> = [];
  let sealed: { path: string; sha: string } | null = null;
  let canonicalNow = CANONICAL;
  const deps: SealDeps = {
    rpc: async (fn, args) => {
      rpcCalls.push([fn, args]);
      if (fn === "prepare_official_reporting_pack") {
        if ((opts.prepare ?? "ready") !== "ready") return { data: { outcome: opts.prepare }, error: null };
        if (sealed) return { data: { outcome: "already_sealed" }, error: null };
        return { data: { outcome: "ready", document: CANONICAL, content_sha256: opts.prepHash ?? shaText(CANONICAL), storage_path: PATH, file_name: "official-reporting-pack-2025.json" }, error: null };
      }
      if (fn === "seal_reporting_pack_server") {
        // The database takes no hash: it regenerates and hashes the canonical document itself.
        if (Object.keys(args).sort().join(",") !== "p_issuance_id,p_storage_path,p_user") return { data: null, error: { message: "unexpected arguments" } };
        const outcome = sealed ? "already_sealed" : opts.seal ?? "sealed";
        if (outcome !== "sealed") return { data: { outcome }, error: null };
        sealed = { path: String(args.p_storage_path), sha: opts.sealHash ?? shaText(CANONICAL) };
        return { data: { outcome, content_sha256: sealed.sha }, error: null };
      }
      if (fn === "reporting_pack_sealed_object") {
        return { data: sealed ? { storage_path: sealed.path, content_sha256: sealed.sha, canonical_sha256: shaText(canonicalNow), company_id: U.co } : null, error: null };
      }
      return { data: null, error: { message: "unexpected" } };
    },
    put: async (p, b) => {
      if (store.has(p)) return { error: { message: "exists" } };
      store.set(p, opts.tamperOnPut ? new TextEncoder().encode("tampered in transit") : b);
      return { error: null };
    },
    remove: async (p) => store.delete(p),
    get: async (p) => store.get(p) ?? null,
    sha256Hex: async (b) => sha(b),
  };
  return { deps, store, rpcCalls, setCanonical: (t: string) => { canonicalNow = t; } };
}


// REPRODUCTION (evidence only): a remove() after an unsealed() check is not atomic with sealing.
describe("REPRO seal race", () => {
  it("a request removing foreign unsealed bytes after its unsealed() check deletes a concurrently SEALED canonical object", async () => {
    const w = world();
    w.store.set(PATH, new TextEncoder().encode(DOCTORED)); // foreign unsealed bytes, same size as the canonical document
    expect(new TextEncoder().encode(DOCTORED).length).toBe(new TextEncoder().encode(CANONICAL).length);
    let release!: () => void; const gate = new Promise<void>((r) => { release = r; });
    let reachedRemove!: () => void; const atRemove = new Promise<void>((r) => { reachedRemove = r; });
    const realRemove = w.deps.remove; let first = true;
    const depsB: SealDeps = { ...w.deps, remove: async (p) => { if (first) { first = false; reachedRemove(); await gate; } return realRemove(p); } };
    const b = issueOfficialPack(depsB, { userId: U.user, issuanceId: U.iss });
    await atRemove;                                   // B saw foreign bytes and "unsealed", and is about to remove
    const a = await issueOfficialPack(w.deps, { userId: U.user, issuanceId: U.iss }); // A replaces them and seals
    expect(a.body.outcome).toBe("sealed");
    release(); const rb = await b;
    const v = await verifyStoredPack(w.deps, U.iss);
    expect(rb.body.outcome).toBe("already_sealed"); // B deleted the sealed object, then re-stored identical canonical bytes
    expect(v.outcome).toBe("intact");
  });
});

describe("REPRO seal race — the window", () => {
  for (const mode of ["verify-during-window", "worker-dies-in-window"] as const) {
    it(mode, async () => {
      const w = world();
      w.store.set(PATH, new TextEncoder().encode(DOCTORED));
      let release!: () => void; const gate = new Promise<void>((r) => { release = r; });
      let reachedRemove!: () => void; const atRemove = new Promise<void>((r) => { reachedRemove = r; });
      let removedB!: () => void; const afterRemoveB = new Promise<void>((r) => { removedB = r; });
      let first = true; let putsByB = 0;
      const depsB: SealDeps = { ...w.deps,
        remove: async (p) => { if (first) { first = false; reachedRemove(); await gate; const r = await w.deps.remove(p); removedB(); return r; } return w.deps.remove(p); },
        put: async (p, b, t) => { putsByB++; if (putsByB === 2) { if (mode === "worker-dies-in-window") throw new Error("worker killed"); await new Promise((r) => setTimeout(r, 20)); } return w.deps.put(p, b, t); } };
      const b = issueOfficialPack(depsB, { userId: U.user, issuanceId: U.iss }).catch((e) => ({ body: { outcome: `crashed: ${e.message}` } }));
      await atRemove;
      const a = await issueOfficialPack(w.deps, { userId: U.user, issuanceId: U.iss });
      release(); await afterRemoveB;
      const during = await verifyStoredPack(w.deps, U.iss);
      const rb = await b;
      const after = await verifyStoredPack(w.deps, U.iss);
      // DEFECT (documented, not fixed here): the sealed pack's object is missing during the window; if the remover dies
      // there, it stays missing (impact query C would find it).
      expect({ a: a.body.outcome, during: during.outcome }).toEqual({ a: "sealed", during: "missing" });
      expect(after.outcome).toBe(mode === "worker-dies-in-window" ? "missing" : "intact");
    });
  }
});
